function countWords(text) {
  const counts = {};
  for (const word of text.split(/\s+/)) {
    if (!word) continue;
    // Remove punctuation and convert to lowercase
    const cleanWord = word.replace(/[^\w]/g, '').toLowerCase();
    if (cleanWord) {
      counts[cleanWord] = (counts[cleanWord] || 0) + 1;
    }
  }
  return counts;
}"}

