// Test case 1: 'The' and 'the' should be counted as the same word
function testCaseInsensitive() {
  const text = 'The quick brown fox. the lazy dog.';
  const result = countWords(text);
  console.log('Test 1 - Case insensitivity:');
  console.log('  Input:', text);
  console.log('  Result:', JSON.stringify(result));

  const theCount = result['the'] || 0;
  if (theCount === 2) {
    console.log('  ✓ PASS: Both "The" and "the" counted as "the" (count = 2)');
  } else {
    console.log('  ✗ FAIL: Expected count 2 for "the", got', theCount);
  }
  console.log();
}

// Test case 2: Punctuation should be stripped
function testPunctuation() {
  const text = 'Hello, world! How are you?';
  const result = countWords(text);
  console.log('Test 2 - Punctuation removal:');
  console.log('  Input:', text);
  console.log('  Result:', JSON.stringify(result));

  const helloCount = result['hello'] || 0;
  const worldCount = result['world'] || 0;
  const howCount = result['how'] || 0;
  const areCount = result['are'] || 0;
  const youCount = result['you'] || 0;

  if (helloCount === 1 && worldCount === 1 && howCount === 1 && areCount === 1 && youCount === 1) {
    console.log('  ✓ PASS: All words counted without punctuation');
  } else {
    console.log('  ✗ FAIL: Punctuation not properly removed');
  }
  console.log();
}

// Test case 3: Combined test - case insensitivity and punctuation
function testCombined() {
  const text = 'The cat. THE dog! the bird.';
  const result = countWords(text);
  console.log('Test 3 - Combined test:');
  console.log('  Input:', text);
  console.log('  Result:', JSON.stringify(result));

  const theCount = result['the'] || 0;
  const catCount = result['cat'] || 0;
  const dogCount = result['dog'] || 0;
  const birdCount = result['bird'] || 0;

  if (theCount === 3 && catCount === 1 && dogCount === 1 && birdCount === 1) {
    console.log('  ✓ PASS: Case-insensitive and punctuation-removed correctly');
  } else {
    console.log('  ✗ FAIL: Combined test failed');
  }
  console.log();
}

// Test case 4: Empty string handling
function testEmptyString() {
  const text = '';
  const result = countWords(text);
  console.log('Test 4 - Empty string:');
  console.log('  Input:', JSON.stringify(text));
  console.log('  Result:', JSON.stringify(result));

  if (Object.keys(result).length === 0) {
    console.log('  ✓ PASS: Empty string returns empty object');
  } else {
    console.log('  ✗ FAIL: Empty string should return empty object');
  }
  console.log();
}

// Run all tests
console.log('=== Running wordcount tests ===\n');
testCaseInsensitive();
testPunctuation();
testCombined();
testEmptyString();
console.log('=== Tests complete ===');
